pm.test("US116 - Maintenance record creation returns 200", function () {
    pm.response.to.have.status(200);
});

pm.test("US116 - Created maintenance record is persisted", function () {
    pm.response.to.have.status(200);

    const records = pm.response.json();
    pm.expect(records).to.be.an("array");

    const record = records.find(r =>
        r.description === "HTTP-Test - Scheduled A-check maintenance"
        && r.template.templateId === Number(
            pm.collectionVariables.get("templateId")
        )
    );

    pm.expect(record, "Created record must appear").to.exist;
    pm.expect(record.aircraftRegistration).to.eql("CS-TUA");
    pm.expect(record.durationHours).to.eql(6.5);
    pm.expect(record.startDate).to.eql("2026-10-28");
    pm.expect(record.status).to.eql("INLINE");
    pm.expect(record.id).to.be.a("number");
    pm.collectionVariables.set("maintenanceRecordId", record.id);
});

pm.test("Saved maintenance template is returned", function () {
    pm.response.to.have.status(200);

    const template = pm.response.json();

    pm.expect(template.templateId)
        .to.eql(Number(pm.collectionVariables.get("templateId")));
    pm.expect(template.name).to.eql("A-Check Engine Inspection");
    pm.expect(template.expectedDuration).to.eql(6.5);
});

pm.test("US117 - Unknown template returns 409", function () {
