    pm.expect(template.name).to.eql("Landing Gear");
    pm.expect(template.expectedDuration).to.eql(3.5);
    pm.expect(template.templateId).to.be.a("number");

    pm.collectionVariables.set("secondTemplateId", template.templateId);
});

pm.test("US117 - List contains both created templates", function () {
    pm.response.to.have.status(200);

    const templates = pm.response.json();
    pm.expect(templates).to.be.an("array");

    const first = templates.find(t =>
        t.templateId === Number(pm.collectionVariables.get("templateId"))
    );

    const second = templates.find(t =>
        t.templateId === Number(pm.collectionVariables.get("secondTemplateId"))
    );

    pm.expect(first, "First template must appear").to.exist;
    pm.expect(first.name).to.eql("A-Check Engine Inspection");
    pm.expect(first.expectedDuration).to.eql(6.5);

    pm.expect(second, "Second template must appear").to.exist;
    pm.expect(second.name).to.eql("Landing Gear");
    pm.expect(second.expectedDuration).to.eql(3.5);
});

