pm.test("US220 - Maintenance costs match bootstrap data", function () {
    pm.response.to.have.status(200);

    const reports = pm.response.json();
    pm.expect(reports).to.be.an("array").with.lengthOf(3);

    const expected = {
        "CS-TUA": 6700,
        "D-ABXA": 5600,
        "F-HXKA": 0
    };

    Object.entries(expected).forEach(([registration, cost]) => {
        const report = reports.find(r => r.group === registration);

        pm.expect(report, registration + " must appear").to.exist;
        pm.expect(report.totalCost).to.eql(cost);
    });
});

pm.test("US220 - Costs are grouped correctly by model", function () {
    pm.response.to.have.status(200);

    const results = pm.response.json();
    pm.expect(results).to.be.an("array").with.lengthOf(2);

    const boeing = results.find(item => item.group === "737-800");
    const airbus = results.find(item => item.group === "A320neo");

    pm.expect(boeing, "737-800 must appear").to.exist;
    pm.expect(airbus, "A320neo must appear").to.exist;

    pm.expect(boeing.totalCost).to.eql(12300);
    pm.expect(airbus.totalCost).to.eql(0);
});

pm.test("US221 - Average turnaround matches bootstrap data", function () {
