    };

    Object.entries(expected).forEach(([model, days]) => {
        const result = results.find(r => r.aircraftType === model);

        pm.expect(result, model + " must appear").to.exist;
        pm.expect(result.averageDays).to.eql(days);
    });
});

pm.test("US222 - Default alerts match maintenance history", function () {
    pm.response.to.have.status(200);

    const alerts = pm.response.json();
    pm.expect(alerts).to.be.an("array").that.is.not.empty;

    ["CS-TUA", "D-ABXA", "F-HXKA"].forEach(registration => {
        const alert = alerts.find(
            a => a.registrationNumber === registration
        );

        pm.expect(alert, registration + " must appear").to.exist;
        pm.expect(alert.lastMaintenanceDate).to.be.a("string");
        pm.expect(alert.daysSinceLastMaintenance).to.be.at.least(0);
        pm.expect(alert.totalFlightHours).to.be.at.least(500);
        pm.expect(alert.alertReason).to.include("threshold of 500");
        pm.expect(alert.alertReason)
            .not.to.include("No completed maintenance on record");
    });

    const withoutMaintenance = alerts.find(
        a => a.registrationNumber === "G-X321"
    );

    pm.expect(withoutMaintenance, "G-X321 must appear").to.exist;
    pm.expect(withoutMaintenance.lastMaintenanceDate).to.eql(null);
    pm.expect(withoutMaintenance.daysSinceLastMaintenance).to.eql(null);
    pm.expect(withoutMaintenance.alertReason)
        .to.include("No completed maintenance on record");
});

