pm.test("US226 - Inventory contains the expected parts and totals", function () {
    pm.response.to.have.status(200);

    const parts = pm.response.json();
    pm.expect(parts).to.be.an("array");

    const expected = [
        ["ENG-001", 2, 3000],
        ["TIRE-900", 4, 3200],
        ["BRAKE-200", 2, 2400],
        ["FUEL-PUMP-01", 1, 3200],
        ["OIL-FILTER-22", 2, 500]
    ];

    expected.forEach(([serial, quantity, cost]) => {
        const part = parts.find(p => p.partSerialNumber === serial);

        pm.expect(part, serial + " must appear").to.exist;
        pm.expect(part.totalQuantityUsed).to.eql(quantity);
        pm.expect(part.totalCost).to.eql(cost);
        pm.expect(part.timesUsedInRecords).to.eql(1);
    });
});

pm.test("US226 - No alerts with threshold 5", function () {
    pm.response.to.have.status(200);
    pm.expect(pm.response.json()).to.deep.equal([]);
});

pm.test("US226 - Usage equal to or above threshold triggers alerts", function () {
    pm.response.to.have.status(200);

    const alerts = pm.response.json();
    pm.expect(alerts).to.be.an("array");

    const engine = alerts.find(p => p.partSerialNumber === "ENG-001");
    const tire = alerts.find(p => p.partSerialNumber === "TIRE-900");

    pm.expect(engine, "Usage equal to threshold must trigger an alert")
        .to.exist;
    pm.expect(engine.totalQuantityUsed).to.eql(2);

    pm.expect(tire, "Usage above threshold must trigger an alert")
        .to.exist;
    pm.expect(tire.totalQuantityUsed).to.eql(4);

    pm.expect(alerts.some(p => p.partSerialNumber === "FUEL-PUMP-01"))
        .to.eql(false);

    alerts.forEach(part => {
        pm.expect(part.totalQuantityUsed).to.be.at.least(2);
        pm.expect(part.alertMessage).to.include("threshold: 2");
    });
});

pm.test("US226 - No alerts with default threshold", function () {
    pm.response.to.have.status(200);
    pm.expect(pm.response.json()).to.deep.equal([]);
});

pm.test("US227 - Aircraft fuel efficiency is calculated correctly", function () {
    pm.response.to.have.status(200);

    const aircraft = pm.response.json();
    pm.expect(aircraft).to.be.an("array").that.is.not.empty;

    aircraft.forEach(item => {
        pm.expect(item.registrationNumber).to.be.a("string");
        pm.expect(item.fuelCapacityLiters).to.be.a("number");
        pm.expect(item.maxRangeKm).to.be.above(0);

        const expected = Math.round(
            item.fuelCapacityLiters / item.maxRangeKm * 100
        ) / 100;

        pm.expect(item.fuelConsumptionLitPerKm).to.eql(expected);
    });
});

pm.test("US227 - Estimated route fuel matches distance and consumption", function () {
    pm.response.to.have.status(200);

    const routes = pm.response.json();
    pm.expect(routes).to.be.an("array").that.is.not.empty;

    routes.forEach(route => {
        pm.expect(route.routeId).to.be.a("number");
        pm.expect(route.distanceKm).to.be.above(0);
        pm.expect(route.avgFuelConsumptionLitPerKm)
            .to.be.a("number").and.at.least(0);

        const expected = Math.round(
            route.distanceKm * route.avgFuelConsumptionLitPerKm * 100
        ) / 100;

        pm.expect(route.estimatedFuelLiters).to.eql(expected);
    });
});
